insert into source_anchors (id, organization_id, file_version_id, fragment_id, anchor_kind, page, locator, quote_text, acquired_by, created_at, created_by) values
  ('a8118fe4-ff78-4162-bd97-bf716fe3aa53', '65f36d85-8a52-4668-8451-adcea4448565', '8fb3ea00-e63a-45e1-8475-651a3fdf2033', '73cf1e6e-1222-4313-b304-5339deafbe49', 'heading_paragraph', null, 'p.12 (1) ガバナンス 第1段落', '当社は、気候変動をはじめとするサステナビリティ関連のリスク及び機会を経営上の重要な課題と位置付けています。取締役会は、サステナビリティ推進部から年1回報告を受け、気候関連の課題への対応状況を監督しています。', 'extracted', '2026-07-01T03:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f'),
  ('a8118ee4-ff78-4faf-b008-0faa9a9dc1c5', '65f36d85-8a52-4668-8451-adcea4448565', '8fb3ea00-e63a-45e1-8475-651a3fdf2033', '73cf1f6e-1222-44c6-ae9a-4e68772cf455', 'heading_paragraph', null, 'p.12 (1) ガバナンス 第2段落', '代表取締役社長を委員長とするサステナビリティ委員会を年2回開催し、気候関連のリスク及び機会の識別と対応方針を審議しています。', 'extracted', '2026-07-01T03:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f'),
  ('e7cafe12-d517-4b8e-b9b3-a01cee5c37f3', '65f36d85-8a52-4668-8451-adcea4448565', 'dfedfc13-43f6-491c-bad2-4cfd4bbb6cf5', 'e1d38aef-91bd-4f29-951c-c7347f8f7e0d', 'heading_paragraph', null, '第2章 2.1 第1段落', '物理的リスク（急性）：西日本工場は近隣河川の氾濫時に浸水が想定される区域に立地している。豪雨の激甚化により、生産設備の浸水と操業停止が生じるおそれがある（中期〜長期）。', 'extracted', '2026-07-23T03:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f'),
  ('104055bd-298c-4120-965e-206fb6acc2b3', '65f36d85-8a52-4668-8451-adcea4448565', 'dfedfc13-43f6-491c-bad2-4cfd4bbb6cf5', 'f8b77626-22cb-4b53-88c8-85a829bc993d', 'heading_paragraph', null, '第2章 2.2 第1段落', '移行リスク（政策・法規制）：炭素価格（カーボンプライシング）の導入や引上げにより、燃料及び購入電力に係る操業コストが上昇するおそれがある（短期〜中期）。', 'extracted', '2026-07-23T03:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f'),
  ('0369a0f1-6ccc-4bc8-a249-2e537d1cd163', '65f36d85-8a52-4668-8451-adcea4448565', 'dfedfc13-43f6-491c-bad2-4cfd4bbb6cf5', '4775c47f-fffb-46dd-8c80-a92a4fe3cf35', 'heading_paragraph', null, '第2章 2.3 第1段落', '機会（製品及びサービス）：顧客の省エネルギー需要の高まりにより、低消費電力型の電子部品の需要が拡大する可能性がある（中期）。', 'extracted', '2026-07-23T03:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f'),
  ('7e136915-2ba0-40a2-b534-1f3093b21917', '65f36d85-8a52-4668-8451-adcea4448565', 'dfedfc13-43f6-491c-bad2-4cfd4bbb6cf5', 'f80e9615-efbb-41cf-ac3a-7ec7b24b3265', 'heading_paragraph', null, '第3章 3.1 第1段落', '上記のリスクの財務的影響額は現在評価中であり、未確定である。浸水時の復旧費用と炭素価格の感応度分析は2026年度下期に完了する予定である。', 'extracted', '2026-07-23T03:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f'),
  ('db5fc586-41d1-498b-99e8-9cf11cd849eb', '65f36d85-8a52-4668-8451-adcea4448565', 'c40e5217-38a8-40a2-91bd-96f78267689d', 'e2e9b4e5-58af-4828-a416-cfd7aa6b5c6f', 'heading_paragraph', null, '第2章 2.1 第1段落', '取締役会は、気候関連の課題を含むサステナビリティ関連のリスク及び機会への対応を監督する。', 'extracted', '2026-07-26T03:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f'),
  ('db5fc686-41d1-4b3e-a1ed-1e5f99d99a7f', '65f36d85-8a52-4668-8451-adcea4448565', 'c40e5217-38a8-40a2-91bd-96f78267689d', 'e2e9b7e5-58af-4d41-b99d-9a7990c3faad', 'heading_paragraph', null, '第2章 2.1 第2段落', 'サステナビリティ委員会は代表取締役社長を委員長とし、年4回開催する。委員会は審議の結果を年2回、取締役会に報告する。', 'extracted', '2026-07-26T03:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f'),
  ('db5fc786-41d1-4cf1-8ecc-bfaf1b5a0a67', '65f36d85-8a52-4668-8451-adcea4448565', 'c40e5217-38a8-40a2-91bd-96f78267689d', 'e2e9b6e5-58af-4b8e-a2e0-b745909d99f7', 'heading_paragraph', null, '第2章 2.2 第1段落', '2026年度より、気候関連の目標の進捗を委員会の定例議題とし、執行役員（サステナビリティ担当）が進捗を報告する。', 'extracted', '2026-07-26T03:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f');
