insert into csrd_disclosure_drafts (id, organization_id, reporting_period_id, section, body, ai_body, covered_item_codes, gaps, ai_run_id, ai_confidence, ai_warnings, ai_generated_at, confirmed_at, confirmed_by, created_at, updated_at, created_by, updated_by) values
  ('5284ec68-91b3-4cb3-b7f6-67f27cc69aa5', '65f36d85-8a52-4668-8451-adcea4448565', '6d6e3a7c-bc1c-4258-a8a1-6850d1cead65', 'ESRS2', '当社は、サステナビリティに関する事項を取締役会が監督し、サステナビリティ委員会（委員長: 代表取締役社長）が四半期ごとに重要な影響・リスク・機会の状況を審議して取締役会へ報告しています（架空）。ダブル・マテリアリティ評価は、従業員・主要サプライヤー・顧客への聞き取りを踏まえてサステナビリティ推進部が行い、評価方法と閾値は自社で定めています（架空）。重要と判断した事項と戦略・ビジネスモデルとの関係は、各テーマ別の節で説明します。本文はデモ用の架空の記載で、実在企業の開示ではありません。', '', '{"ESRS2-GOV-1"}', '[]'::jsonb, null, null, '{}', null, null, null, '2026-08-05T03:00:00.000Z', '2026-08-06T03:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f'),
  ('57d21f2f-5348-4a78-bdf7-6d0805717ccd', '65f36d85-8a52-4668-8451-adcea4448565', '6d6e3a7c-bc1c-4258-a8a1-6850d1cead65', 'S1', '', '青海テクノロジー株式会社は、自社の労働力（S1）をインパクトと財務の両面で重要と判断しました（架空）。主なインパクトは長時間労働による健康への影響（潜在・人権）、主なリスクは人材確保難による操業への影響です（架空）。2026年度においては、従業員数の内訳（ESRS-S1-6）について開示しています。なお、1 件の要求事項（ESRS-S1-9）は担当者の確認が済んでいないため記載を保留しています（デモ生成）。', '{"ESRS-S1-6"}', '[{"itemCode":"ESRS-S1-9","reason":"担当者の確認が済んでいないため、草案に含めていません。"}]'::jsonb, null, 0.58, '{"これは草案です（デモ生成）。そのまま開示せず、担当者が本文に採用して内容を確認してから確定してください。"}', '2026-08-04T03:00:00.000Z', null, null, '2026-08-04T03:00:00.000Z', '2026-08-04T03:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f');
insert into narrative_versions (id, organization_id, narrative_record_id, version_no, reporting_period_id, scope_note, fields, body, source_anchor_ids, carried_from_version_id, change_reason, originated_from_ai_run_id, iro_refs, content_hash, created_at, created_by) values
  ('7cb1ec23-37f6-485f-a64a-178c76f9b36b', '65f36d85-8a52-4668-8451-adcea4448565', '87ed6e29-5c2e-4efa-8145-39f1901292f3', 1, '6d6e3d7c-bc1c-4771-932b-c758a0c5920b', '青海テクノロジー株式会社及び連結子会社（2025年度）', '{"oversightBody":"取締役会","oversightProcess":"サステナビリティ推進部から年1回報告を受け、気候関連の課題への対応状況を監督する","committee":"サステナビリティ委員会（委員長: 代表取締役社長／年2回開催）"}'::jsonb, '取締役会は、サステナビリティ推進部から年1回報告を受け、気候関連の課題への対応状況を監督しています。代表取締役社長を委員長とするサステナビリティ委員会を年2回開催し、気候関連のリスク及び機会の識別と対応方針を審議しています。', '{"a8118fe4-ff78-4162-bd97-bf716fe3aa53","a8118ee4-ff78-4faf-b008-0faa9a9dc1c5"}', null, '前年度（FY2025）の有価証券報告書の記載を台帳へ登録', null, '{}', 'fbf6dfd80c6a6d01ed20847c333f6f16', '2026-07-01T04:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f'),
  ('7cb1ed23-37f6-4a12-b5bc-a206cae70467', '65f36d85-8a52-4668-8451-adcea4448565', '87ed6e29-5c2e-4efa-8145-39f1901292f3', 2, '6d6e3a7c-bc1c-4258-a8a1-6850d1cead65', '青海テクノロジー株式会社及び連結子会社（2026年度）', '{"oversightBody":"取締役会","oversightProcess":"サステナビリティ委員会から年2回報告を受け、気候関連の課題を含むリスク及び機会への対応を監督する","committee":"サステナビリティ委員会（委員長: 代表取締役社長／年4回開催）","managementRole":"執行役員（サステナビリティ担当）が気候関連の目標の進捗を委員会に報告する"}'::jsonb, '取締役会は、気候関連の課題を含むサステナビリティ関連のリスク及び機会への対応を監督しています。代表取締役社長を委員長とするサステナビリティ委員会を年4回開催し、その審議の結果を年2回、取締役会に報告しています。', '{"db5fc586-41d1-498b-99e8-9cf11cd849eb","db5fc686-41d1-4b3e-a1ed-1e5f99d99a7f","db5fc786-41d1-4cf1-8ecc-bfaf1b5a0a67"}', '7cb1ec23-37f6-485f-a64a-178c76f9b36b', '第3回サステナビリティ委員会資料に基づき、委員会の開催頻度と取締役会への報告頻度を更新', null, '{}', '53e6b947f8e1a97a9514168301dbaebc', '2026-07-27T03:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f'),
  ('f3318fff-f002-45ab-8852-97e3317dbdd5', '65f36d85-8a52-4668-8451-adcea4448565', '15fa005b-7380-47d8-bac7-3b69ab670279', 1, '6d6e3a7c-bc1c-4258-a8a1-6850d1cead65', '青海テクノロジー株式会社及び連結子会社（2026年度）', '{"riskCategory":"物理的リスク（急性）","description":"近隣河川の氾濫による生産設備の浸水と操業停止","timeHorizon":"中期〜長期","affectedAssets":"西日本工場"}'::jsonb, '西日本工場は近隣河川の氾濫時に浸水が想定される区域に立地しており、豪雨の激甚化により生産設備の浸水と操業停止が生じるおそれがあります（物理的リスク・中期〜長期）。', '{"e7cafe12-d517-4b8e-b9b3-a01cee5c37f3"}', null, '気候関連リスク・機会 評価資料 2026 から登録', null, '{"4b283f00-3518-459a-8bc6-5fe56bcef971"}', '8cd61bdb3127e8a293b3f3b111c3d63c', '2026-07-23T05:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f'),
  ('8a8da3d4-7ccd-476c-ba15-e5bff7915f4f', '65f36d85-8a52-4668-8451-adcea4448565', '596dbd79-26f3-4557-b60c-88e9e49a5c25', 1, '6d6e3a7c-bc1c-4258-a8a1-6850d1cead65', '青海テクノロジー株式会社及び連結子会社（2026年度）', '{"riskCategory":"移行リスク（政策・法規制）","description":"炭素価格の導入・引上げによる燃料及び購入電力に係る操業コストの上昇","timeHorizon":"短期〜中期","affectedAssets":"国内の生産拠点"}'::jsonb, '炭素価格（カーボンプライシング）の導入や引上げにより、燃料及び購入電力に係る操業コストが上昇するおそれがあります（移行リスク・短期〜中期）。', '{"104055bd-298c-4120-965e-206fb6acc2b3"}', null, '気候関連リスク・機会 評価資料 2026 から登録', null, '{"4b283f00-3518-459a-8bc6-5fe56bcef971"}', '8118e712867f8704b6491e0bb92d4f14', '2026-07-23T05:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f'),
  ('e0d34b1a-93c3-442f-a8e1-3d767311ec4b', '65f36d85-8a52-4668-8451-adcea4448565', '7baf7e48-0c6c-401a-929f-f701ca99e733', 1, '6d6e3a7c-bc1c-4258-a8a1-6850d1cead65', '青海テクノロジー株式会社及び連結子会社（2026年度）', '{"relatedRisk":"西日本工場の浸水（物理的リスク）／炭素価格の導入・引上げ（移行リスク）","impactDescription":"浸水時の復旧費用と操業停止による売上の減少、炭素価格による操業コストの上昇","estimationStatus":"評価中（未確定）","noAmountReason":"財務的影響額は評価中のため未確定（感応度分析は2026年度下期に完了する予定）"}'::jsonb, 'これらのリスクの財務的影響額は現在評価中であり、未確定です。浸水時の復旧費用と炭素価格の感応度分析は2026年度下期に完了する予定です。', '{"7e136915-2ba0-40a2-b534-1f3093b21917"}', null, '気候関連リスク・機会 評価資料 2026 から登録', null, '{}', '904bbc742dbd96976313c901d31df532', '2026-07-24T06:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f'),
  ('8a1308dc-86e8-4b52-9d6e-4c214ff9ac6f', '65f36d85-8a52-4668-8451-adcea4448565', '53884e18-a776-489f-b90e-788df8f1169d', 1, '6d6e3a7c-bc1c-4258-a8a1-6850d1cead65', '青海テクノロジー株式会社及び連結子会社（2026年度）', '{"relatedRiskOpportunity":"顧客の省エネルギー需要の高まり（機会）","initiative":"低消費電力型の電子部品の開発と拡販"}'::jsonb, '顧客の省エネルギー需要の高まりを機会と捉え、低消費電力型の電子部品の開発と拡販に取り組んでいます。', '{"0369a0f1-6ccc-4bc8-a249-2e537d1cd163"}', null, '気候関連リスク・機会 評価資料 2026 から登録', null, '{}', '11d29a55a3e839440785ded45a13a138', '2026-07-24T06:00:00.000Z', 'ca0d35cc-f990-481f-bf1c-3f121fadea1f');
